using Ganss.XSS;

[FormControlAttribute('TFMHtmlViewerCtrl','/resources/html/TFMHtmlViewerCtrl',classstr(TFMHtmlViewerCtrlBuild))]
class TFMHtmlViewerCtrl extends FormTemplateControl
{
    FormProperty  addCopyLinkProperty;
    FormProperty  htmlProperty;
    FormProperty  formatAsXmlProperty;
    FormProperty  showProgressInformationProperty;
    HtmlSanitizer sanitizer;
    boolean       skipSanitizer;

}

Method.Source:
[FormPropertyAttribute(FormPropertyKind::Value, 'Html', true, false)]
public str parmHtml(str _value = htmlProperty.parmValue())
{
    if(!skipSanitizer && !prmisDefault(_value) && !this.parmFormatAsXml() )
    {
        //sanitize before setting
        sanitizer = this.getSanitizer();
        str safeHTML = sanitizer.Sanitize(_value, "", null);

        htmlProperty.setValueOrBinding(safeHTML);
    } 
    else
    {
        htmlProperty.setValueOrBinding(_value);
    }
    return htmlProperty.parmValue();
}

[FormPropertyAttribute(FormPropertyKind::Value, 'HtmlAddCopyLink', true, false)]
public str parmAddCopyLink(str _value = addCopyLinkProperty.parmValue())
{
    if(!prmisDefault(_value))
    {
        addCopyLinkProperty.setValueOrBinding(_value);
    }
    return addCopyLinkProperty.parmValue();
}

[FormPropertyAttribute(FormPropertyKind::Value, 'FormatAsXml', true, false)]
public str parmFormatAsXml(str _value = formatAsXmlProperty.parmValue())
{
    if(!prmisDefault(_value))
    {
        formatAsXmlProperty.setValueOrBinding(_value);
    }
    return formatAsXmlProperty.parmValue();
}

[FormPropertyAttribute(FormPropertyKind::Value, 'ShowProgressInformation', true, false)]
public str parmShowProgressInformation(str _value = showProgressInformationProperty.parmValue())
{
    if(!prmisDefault(_value))
    {
        showProgressInformationProperty.setValueOrBinding(_value);
    }
    return showProgressInformationProperty.parmValue();
}

public boolean parmSkipSanitizer(boolean _skipSanitizer = skipSanitizer)
{
    skipSanitizer = _skipSanitizer;
    return skipSanitizer;
}

public void new(FormBuildControl _build, FormRun _formRun)
{
    super(_build, _formRun);

    this.setTemplateId('TFMHtmlViewerCtrl');
    this.setResourceBundleName('/resources/html/TFMHtmlViewerCtrl');

    // Create properties for the control
    addCopyLinkProperty = this.addProperty(methodStr(TFMHtmlViewerCtrl, parmAddCopyLink), Types::String);
    htmlProperty = this.addProperty(methodStr(TFMHtmlViewerCtrl, parmHtml), Types::String);
    formatAsXmlProperty = this.addProperty(methodStr(TFMHtmlViewerCtrl, parmFormatAsXml), Types::String);
    showProgressInformationProperty = this.addProperty(methodStr(TFMHtmlViewerCtrl, parmShowProgressInformation), Types::String);
}

public void applyBuild()
{
    TFMHtmlViewerCtrlBuild build;

    super();

    build = this.build() as TFMHtmlViewerCtrlBuild;
    if(build)
    {
        this.parmAddCopyLink(build.addCopyLinkField());
        this.parmHtml(build.htmlField());
        this.parmFormatAsXml(build.formatAsXmlField());
    }
}

 public HtmlSanitizer getSanitizer(){

     if(!sanitizer)
     {
         sanitizer = new TFMHtmlSanitizer().getSanitizer();
     }
     return sanitizer;
}
